WITH latest_match AS (SELECT s.id, s.supplier_name, s.city, s.rating, top1.price FROM suppliers s LEFT JOIN LATERAL (SELECT c.price FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT city, COUNT(*) AS event_count, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE city = 'Tokyo') AS tokyo_rows, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, AVG(rating) FILTER (WHERE city = 'New York') AS new_york_avg_rating, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS price_per_london FROM latest_match GROUP BY city;
